// One-off (probe-go branch): what GA4 counts right now and today, as the live dashboard would ask it. Aggregates only.
import crypto from "node:crypto";
const sa = JSON.parse(process.env.GA_SERVICE_ACCOUNT_JSON), P = process.env.GA_PROPERTY_ID || "557990379";
const b64 = o => Buffer.from(typeof o === "string" ? o : JSON.stringify(o)).toString("base64url"), now = Math.floor(Date.now() / 1000);
const un = b64({alg: "RS256", typ: "JWT"}) + "." + b64({iss: sa.client_email, scope: "https://www.googleapis.com/auth/analytics.readonly", aud: "https://oauth2.googleapis.com/token", iat: now, exp: now + 3600});
const jwt = un + "." + crypto.createSign("RSA-SHA256").update(un).sign(sa.private_key).toString("base64url");
const tok = (await (await fetch("https://oauth2.googleapis.com/token", {method: "POST", headers: {"content-type": "application/x-www-form-urlencoded"}, body: "grant_type=urn:ietf:params:oauth:grant-type:jwt-bearer&assertion=" + jwt})).json()).access_token;
const call = async (kind, body) => { const r = await fetch(`https://analyticsdata.googleapis.com/v1beta/properties/${P}:${kind}`, {method: "POST", headers: {authorization: "Bearer " + tok, "content-type": "application/json"}, body: JSON.stringify(body)}); const j = await r.json(); if (!r.ok) return console.log("ERR", kind, JSON.stringify(j).slice(0, 300)); return j.rows || []; };
const show = (title, rows) => { console.log("\n## " + title); for (const r of rows || []) console.log((r.dimensionValues || []).map(x => x.value).join(" | ") + "  =>  " + r.metricValues.map(x => x.value).join(" / ")); };
const REAL = {orGroup: {expressions: [{filter: {fieldName: "platform", stringFilter: {value: "web"}}}, {filter: {fieldName: "countryId", stringFilter: {value: "IL"}}}]}};
console.log("at", new Date().toISOString());
show("realtime 30 min: users by platform, stream (activeUsers)", await call("runRealtimeReport", {dimensions: [{name: "platform"}, {name: "streamName"}], metrics: [{name: "activeUsers"}]}));
show("realtime 30 min: users by platform, country", await call("runRealtimeReport", {dimensions: [{name: "platform"}, {name: "countryId"}], metrics: [{name: "activeUsers"}], limit: 30}));
show("realtime 30 min: events by platform (eventCount / activeUsers)", await call("runRealtimeReport", {dimensions: [{name: "platform"}, {name: "eventName"}], metrics: [{name: "eventCount"}, {name: "activeUsers"}], limit: 60}));
show("realtime 30 min, dashboard filter REAL: events (eventCount)", await call("runRealtimeReport", {dimensions: [{name: "eventName"}], metrics: [{name: "eventCount"}], dimensionFilter: REAL, limit: 40}));
show("realtime per 5 minutes ago (all, eventCount)", (await call("runRealtimeReport", {dimensions: [{name: "minutesAgo"}], metrics: [{name: "eventCount"}, {name: "activeUsers"}], limit: 40})).sort((a, b) => a.dimensionValues[0].value - b.dimensionValues[0].value));
const d = (s, e) => ({startDate: s, endDate: e});
show("today: link_landing by kind | via (events / users)", await call("runReport", {dateRanges: [d("today", "today")], dimensions: [{name: "customEvent:kind"}, {name: "customEvent:via"}], metrics: [{name: "eventCount"}, {name: "totalUsers"}], dimensionFilter: {filter: {fieldName: "eventName", stringFilter: {value: "link_landing"}}}}));
show("today: events by platform (events / users)", await call("runReport", {dateRanges: [d("today", "today")], dimensions: [{name: "platform"}, {name: "eventName"}], metrics: [{name: "eventCount"}, {name: "totalUsers"}], limit: 80}));
show("today: as the sources drawer asks (platform | sessionSource | sessionMedium | event)", await call("runReport", {dateRanges: [d("today", "today")], dimensions: [{name: "platform"}, {name: "sessionSource"}, {name: "sessionMedium"}, {name: "eventName"}], metrics: [{name: "eventCount"}], dimensionFilter: {andGroup: {expressions: [{filter: {fieldName: "eventName", inListFilter: {values: ["session_start", "car_lookup"]}}}, REAL]}}, limit: 100}));
show("last 7 days: as the sources drawer asks", await call("runReport", {dateRanges: [d("7daysAgo", "yesterday")], dimensions: [{name: "platform"}, {name: "sessionSource"}, {name: "sessionMedium"}, {name: "eventName"}], metrics: [{name: "eventCount"}], dimensionFilter: {andGroup: {expressions: [{filter: {fieldName: "eventName", inListFilter: {values: ["session_start", "car_lookup"]}}}, REAL]}}, limit: 100}));
show("last 7 days: web events by firstUserSource (events)", await call("runReport", {dateRanges: [d("7daysAgo", "today")], dimensions: [{name: "firstUserSource"}, {name: "eventName"}], metrics: [{name: "eventCount"}], dimensionFilter: {filter: {fieldName: "platform", stringFilter: {value: "web"}}}, limit: 60}));
